import React, { useState, useEffect } from 'react';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, ReferenceArea, Label 
} from 'recharts';
import { 
  ArrowLeft, Calendar, ChevronDown, AlertCircle, 
  Search, Users, Activity, Settings, Pill
} from 'lucide-react';

const API_BASE = "http://127.0.0.1:5000/api";

function App() {
  const [view, setView] = useState('overview');
  const [patients, setPatients] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [clinicalData, setClinicalData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const [startIndex, setStartIndex] = useState(0);
  const [windowSize, setWindowSize] = useState(14);

  useEffect(() => {
    fetch(`${API_BASE}/patients`)
      .then(res => res.json())
      .then(json => { if (json.status === "success") setPatients(json.data); })
      .catch(err => console.error(err))
      .finally(() => setIsLoading(false));
  }, []);

  const handleSelectPatient = (p) => {
    setSelectedPatient(p);
    setClinicalData(p.clinicalData);
    setStartIndex(0);
    setView('dashboard');
  };

  const renderSidebar = () => (
    <div className="w-72 bg-white border-r border-slate-100 flex flex-col p-8 print:hidden">
      <div className="flex items-center gap-3 mb-12 px-2">
        <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-200">
          <Activity size={22} className="text-white" />
        </div>
        <span className="text-2xl font-black italic tracking-tighter text-slate-800">ADR <span className="text-blue-600">PRO</span></span>
      </div>
      <nav className="flex-1 space-y-2">
        <button onClick={() => setView('overview')} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-bold transition-all ${view === 'overview' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}>
          <Users size={20} /> 患者住院紀錄
        </button>
        <button onClick={() => setView('search')} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-bold transition-all ${view === 'search' ? 'bg-blue-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}>
          <Search size={20} /> 藥物查詢
        </button>
      </nav>
    </div>
  );

  const renderDashboard = () => {
    if(!clinicalData) return <div className="flex-1 flex items-center justify-center">載入中...</div>;
    const visibleTrends = clinicalData.trends.slice(startIndex, startIndex + windowSize);

    return (
      <div className="flex-1 p-8 overflow-y-auto bg-[#F8FAFC]">
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl shadow-sm hover:bg-slate-50">
              <ArrowLeft size={18} />
            </button>
            <div className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 font-bold text-slate-700 shadow-sm">
              <Calendar size={16} className="text-blue-500"/> 2024/05/01 - 2024/05/11
            </div>
          </div>
          <div className="flex gap-2">
            {[3, 7, 14].map(d => (
              <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold text-xs" : "px-6 py-2 bg-white text-slate-400 border font-bold text-xs shadow-sm"}>{d}D</button>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm mb-8">
          <div className="h-80 w-full mb-6">
            <ResponsiveContainer>
              <LineChart data={visibleTrends} margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 'bold'}} />
                <YAxis yAxisId="na" domain={[120, 160]} axisLine={false} tickLine={false} tick={{fill: '#F97316', fontSize: 10, fontWeight: 'bold'}} width={40} />
                <YAxis yAxisId="k" orientation="right" domain={[2, 8]} axisLine={false} tickLine={false} tick={{fill: '#6366F1', fontSize: 10, fontWeight: 'bold'}} width={40} />
                <Tooltip contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontWeight: 'bold' }} />
                <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05} stroke="none" />
                <ReferenceArea yAxisId="k" y1={3.5} y2={5.0} fill="#6366F1" fillOpacity={0.05} stroke="none" />
                <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={5} dot={{r: 6, fill: '#F97316', stroke: '#fff', strokeWidth: 3}} isAnimationActive={false} />
                <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={5} dot={{r: 6, fill: '#6366F1', stroke: '#fff', strokeWidth: 3}} isAnimationActive={false} />
              </LineChart>
            </ResponsiveContainer>
          </div>

          <div className="px-10 mb-12">
            <input type="range" min="0" max={Math.max(0, clinicalData.trends.length - windowSize)} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />
            <div className="flex justify-between text-[10px] font-black text-slate-400 mt-4 uppercase">
              <span>住院開始 (05/01)</span>
              <span className="text-blue-600 font-bold bg-blue-50 px-4 py-1.5 rounded-full border border-blue-100 italic">平移檢視: {visibleTrends[0]?.date} - {visibleTrends[visibleTrends.length-1]?.date}</span>
              <span>住院結束 (05/11)</span>
            </div>
          </div>

          <div className="space-y-4 pt-10 border-t border-slate-100">
            {clinicalData.gantt.map((med, i) => {
              const left = Math.max(0, ((med.startIdx - startIndex) / windowSize) * 100);
              const right = Math.min(100, ((med.endIdx - startIndex + 1) / windowSize) * 100);
              const width = Math.max(0, right - left);
              return (
                <div key={i} className="flex items-center">
                  <div className="w-48 text-left pr-4">
                    <p className="text-[11px] font-black text-slate-700 italic uppercase">{med.name}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase">{med.type}</p>
                  </div>
                  <div className="flex-1 h-10 bg-slate-50 rounded-xl relative overflow-hidden border border-slate-100">
                    {width > 0 && (
                      <div className="absolute h-full opacity-80 rounded-lg shadow-sm flex items-center px-4 transition-all" style={{ left: left + '%', width: width + '%', backgroundColor: med.color }}>
                        <span className="text-[8px] text-white font-black uppercase whitespace-nowrap">{med.startDate} - {med.endDate}</span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white rounded-3xl p-10 border border-slate-100 shadow-sm mb-12 text-left">
          <div className="bg-rose-50/50 p-6 -m-10 mb-10 rounded-t-3xl border-b border-rose-100 flex items-center gap-3">
            <AlertCircle className="text-rose-500"/><h2 className="text-rose-900 font-black italic text-xl uppercase tracking-tighter">ADR 關聯分析結論</h2>
          </div>
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest">
              <tr><th className="p-8 text-left">臨床肇因藥物</th><th className="p-8 text-left">影響維度</th><th className="p-8 text-center">檢驗值變化</th><th className="p-8 text-right">智慧判定結果</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {clinicalData.gantt.map((med, i) => (
                <tr key={i} className="hover:bg-rose-50/30 transition-all">
                  <td className="p-8 font-black text-slate-700 italic">{med.name}</td>
                  <td className="p-8 text-slate-400 font-bold uppercase">{med.type}</td>
                  <td className="p-8 font-mono font-black text-2xl italic text-center text-rose-500">{med.impact}</td>
                  <td className="p-8 text-right">
                    <span className="px-10 py-4 rounded-3xl text-xs font-black uppercase text-white shadow-xl inline-block" style={{ backgroundColor: med.level.includes('高') ? '#F43F5E' : med.level.includes('中') ? '#F97316' : '#94A3B8' }}>{med.level}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderSearch = () => (
    <div className="flex-1 p-12 overflow-y-auto">
      <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tighter">藥物與檢驗值關聯查詢</h1>
      <div className="max-w-4xl bg-white rounded-3xl p-10 shadow-sm border border-slate-100 text-left">
        <div className="relative mb-8">
          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
          <input type="text" placeholder="輸入藥物名稱 (例如: Furosemide)..." className="w-full pl-16 pr-8 py-6 bg-slate-50 border-none rounded-2xl text-xl font-bold focus:ring-4 focus:ring-blue-100 transition-all outline-none" />
        </div>
        <div className="grid grid-cols-2 gap-6">
          <div className="p-6 bg-orange-50 rounded-2xl border border-orange-100">
            <h3 className="text-orange-700 font-black mb-2 flex items-center gap-2"><Pill size={18}/> 常見高風險藥物</h3>
            <ul className="text-sm text-orange-600 font-bold space-y-2">
              <li>• Furosemide (電解質異常)</li>
              <li>• KCl Injection (高血鉀)</li>
              <li>• Spironolactone (鉀離子變動)</li>
            </ul>
          </div>
          <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100">
            <h3 className="text-blue-700 font-black mb-2 flex items-center gap-2"><Activity size={18}/> 關聯指標</h3>
            <p className="text-sm text-blue-600 font-bold leading-relaxed">系統將自動比對藥物投與時間與 Na+/K+ 檢驗值變化之斜率關聯。</p>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-left overflow-hidden">
      {renderSidebar()}
      {view === 'overview' && (
        <div className="flex-1 p-12 overflow-y-auto">
          <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tighter">患者住院紀錄</h1>
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden max-w-6xl">
            <table className="w-full text-left">
              <thead className="bg-white border-b text-slate-400 text-[11px] font-bold uppercase tracking-widest">
                <tr><th className="py-6 px-8">病歷 ID</th><th className="py-6 px-8">病患</th><th className="py-6 px-8 text-center">Na+ / K+</th><th className="py-6 px-8 text-right pr-12">監測狀態</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {patients.map(p => (
                  <tr key={p.id} onClick={() => handleSelectPatient(p)} className="hover:bg-blue-50/50 transition-all cursor-pointer group">
                    <td className="py-6 px-8 font-black text-blue-600 text-sm">{p.id}</td>
                    <td className="py-6 px-8 text-slate-700 font-bold text-sm">{p.name} <span className="text-slate-400 font-normal ml-1">{p.info}</span></td>
                    <td className="py-6 px-8 font-sans font-bold text-base text-center"><span className="text-slate-700">{p.na}</span> / <span className="text-slate-700">{p.k}</span></td>
                    <td className="py-6 px-8 text-right pr-12"><span className="bg-rose-50 text-rose-600 px-5 py-1.5 rounded-full text-[11px] font-bold border border-rose-100">{p.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {view === 'dashboard' && renderDashboard()}
      {view === 'search' && renderSearch()}
    </div>
  );
}

export default App;
